CREATE TRIGGER partner_participant_protect_delete BEFORE DELETE ON lesson_participants WHEN EXISTS(SELECT 1 FROM lessons WHERE tenant_id=OLD.tenant_id AND id=OLD.lesson_id AND source_course_id IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM partner_write_guards WHERE tenant_id=OLD.tenant_id) AND NOT EXISTS(SELECT 1 FROM trusted_imports WHERE tenant_id=OLD.tenant_id) BEGIN SELECT RAISE(ABORT,'partner_readonly'); END;
